// Asteroid Dodger – minimal implementation
// Canvas with id "game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const width = (canvas.width = canvas.offsetWidth);
  const height = (canvas.height = canvas.offsetHeight);

  // ----- Game objects -----
  const ship = {
    x: width / 2,
    y: height / 2,
    angle: 0,
    vx: 0,
    vy: 0,
    radius: 10,
    shield: false,
    shieldTimer: 0,
  };

  class Asteroid {
    constructor() {
      const edge = Math.floor(Math.random() * 4);
      // spawn on random edge
      if (edge === 0) { // top
        this.x = Math.random() * width;
        this.y = -20;
      } else if (edge === 1) { // right
        this.x = width + 20;
        this.y = Math.random() * height;
      } else if (edge === 2) { // bottom
        this.x = Math.random() * width;
        this.y = height + 20;
      } else { // left
        this.x = -20;
        this.y = Math.random() * height;
      }
      const speed = 0.5 + Math.random() * 1.5;
      const angle = Math.atan2(ship.y - this.y, ship.x - this.x);
      this.vx = Math.cos(angle) * speed;
      this.vy = Math.sin(angle) * speed;
      this.radius = 15 + Math.random() * 10;
    }
    update() {
      this.x += this.vx;
      this.y += this.vy;
      // wrap around
      if (this.x < -30) this.x = width + 30;
      if (this.x > width + 30) this.x = -30;
      if (this.y < -30) this.y = height + 30;
      if (this.y > height + 30) this.y = -30;
    }
    draw() {
      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.strokeStyle = 'gray';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(0, 0, this.radius, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }
  }

  class PowerUp {
    constructor() {
      this.x = Math.random() * width;
      this.y = Math.random() * height;
      this.radius = 8;
      this.active = true;
    }
    draw() {
      if (!this.active) return;
      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.fillStyle = 'lime';
      ctx.beginPath();
      ctx.arc(0, 0, this.radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
  }

  const asteroids = [];
  let powerUp = null;
  let gameOver = false;

  // ----- Input handling -----
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.code] = true; });
  window.addEventListener('keyup', e => { keys[e.code] = false; });

  function updateShip() {
    if (keys['ArrowLeft']) ship.angle -= 0.07;
    if (keys['ArrowRight']) ship.angle += 0.07;
    if (keys['ArrowUp']) {
      const thrust = 0.1;
      ship.vx += Math.cos(ship.angle) * thrust;
      ship.vy += Math.sin(ship.angle) * thrust;
    }
    // apply friction
    ship.vx *= 0.99;
    ship.vy *= 0.99;
    ship.x += ship.vx;
    ship.y += ship.vy;
    // wrap ship
    if (ship.x < 0) ship.x += width;
    if (ship.x > width) ship.x -= width;
    if (ship.y < 0) ship.y += height;
    if (ship.y > height) ship.y -= height;
    // shield timer
    if (ship.shield) {
      ship.shieldTimer -= 1 / 60;
      if (ship.shieldTimer <= 0) ship.shield = false;
    }
  }

  function spawnAsteroid() {
    if (asteroids.length < 10) asteroids.push(new Asteroid());
  }

  function spawnPowerUp() {
    if (!powerUp) powerUp = new PowerUp();
  }

  function checkCollisions() {
    // ship vs asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.radius + ship.radius) {
        if (ship.shield) {
          // destroy asteroid, consume shield
          asteroids.splice(i, 1);
          ship.shield = false;
        } else {
          gameOver = true;
        }
      }
    }
    // ship vs power‑up
    if (powerUp && powerUp.active) {
      const dx = powerUp.x - ship.x;
      const dy = powerUp.y - ship.y;
      if (Math.hypot(dx, dy) < powerUp.radius + ship.radius) {
        ship.shield = true;
        ship.shieldTimer = 5; // seconds
        powerUp.active = false;
        powerUp = null;
      }
    }
  }

  function drawShip() {
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.fillStyle = ship.shield ? 'cyan' : 'white';
    ctx.beginPath();
    ctx.moveTo(12, 0);
    ctx.lineTo(-8, -6);
    ctx.lineTo(-8, 6);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    drawShip();
    asteroids.forEach(a => a.draw());
    if (powerUp) powerUp.draw();
    if (gameOver) {
      ctx.fillStyle = 'red';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  // ----- Main loop -----
  let lastAsteroidSpawn = 0;
  let lastPowerSpawn = 0;
  function loop(timestamp) {
    if (gameOver) { draw(); return; }
    const delta = timestamp - (lastAsteroidSpawn || timestamp);
    if (delta > 2000) { // spawn every 2 seconds
      spawnAsteroid();
      lastAsteroidSpawn = timestamp;
    }
    if (timestamp - lastPowerSpawn > 10000) { // power‑up every 10 s
      spawnPowerUp();
      lastPowerSpawn = timestamp;
    }
    updateShip();
    asteroids.forEach(a => a.update());
    checkCollisions();
    draw();
    requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
})();
